import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第98章 取消","description":"","frontmatter":{},"headers":[],"relativePath":"第98章_取消.md","filePath":"第98章_取消.md"}'),_={name:"第98章_取消.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第98章-取消" tabindex="-1">第98章 取消 <a class="header-anchor" href="#第98章-取消" aria-label="Permalink to &quot;第98章 取消&quot;">​</a></h1><p>六点零四分，屏幕上进来一句&quot;我今天来不了&quot;。</p><p>我那时候正在把登机牌从塑料套里抽出来。那张纸卡在半透明的套子里，我捏着它边角，捏到起毛，才想起来去读第二行。</p><p>她妈早上血压高。她要带人去一个医院。号是九点的。</p><p>大厅的广播在报一班我没买的航班，报完换成了另一种语言，中间夹着推车压过地砖的声音。我把手机举高了一点，好像这样能看得快些。</p><p>她说她五点半被她妈叫醒，她妈说话含含糊糊，她站在那里没动。</p><p>怕一开口就哭。</p><p>她说这一辈子她妈生病她一次也没哭过。因为她要哭了，她妈就要起来安慰她。</p><p>我不许她起来。</p><p>这六个字我看见的时候，我正用两只手把那个小箱子从地上抬到旁边的空位上。箱子有一点点重。我放到一半停在那儿，停得很难看，前面一个拖大箱子的人绕了我一圈，骂了一句什么。</p><p>我让他过去。我说她讲得对。我说你今天先带你妈把号挂上，我这边你不用管。</p><p>她回了一句：我知道你不用我管。你这个人在机场里能坐一整天。</p><p>我以为这句话后面要跟一句道歉。她没有。她隔了大概十分钟，发回来一个订单截图。</p><p>一杯咖啡，一个面包，四十块，送到我们这边的机场，送到 B 口。</p><p>我那时候坐在第三排。这个我自己没注意，是她讲出来我才知道的。她说她从玻璃外头一张很旧的照片里认出了这一排椅子，扶手那里缠过一圈白胶带，她们那个机场也进过这一种。</p><p>我说我这把没有胶带。</p><p>她说那你在第三排，一二排是宽的。</p><p>我看着那张截图发了三十秒的呆。停机坪上一辆加油车绕着同一架飞机转，转得很慢。我说你别花这个钱。她说她今天就是在花四十块钱，让她自己不要想那个台阶。</p><p>她说她要是今天连四十块都不敢花，她这一天就完了。</p><p>我这边没法讲&quot;我陪你&quot;这种话。我讲的还是那一句你先把号挂上。</p><p>她把东西点好了，让我二十分钟以后下去拿。她说她挂号完了，人在走廊上坐着，她妈在里面量血压。她说她今天没带本子，不能画，也不能想别的，只能看着我这边。</p><p>她那边的时间我算得出来。我说我这里九点四十。她说我这里十点四十。</p><p>我们两个那天第一次只差一个钟头。</p><p>我把这句话往回咽了一下，没咽住。我说，我们两个这一辈子，时间从来没有像今天这么近过。</p><p>她隔了一会儿回：然后我今天来不了。</p><p>后来她讲了一句让我笑不出来的话。她说我今年讲话很像我妈。我说哪里像。她说不管发生什么，你先让人把那件事办完。她说我要是今天讲一句&quot;你不用来&quot;，她就真的不用来了；我要是讲一句&quot;我在这儿等&quot;，她今天就要从她们医院那个走廊上跑出去。</p><p>她说她两头都怕。</p><p>我说我不知道该讲哪一句。</p><p>她说，那你别讲，你去拿你的咖啡。</p><p>那个取餐台在 B 口的下楼梯口，一个穿蓝马甲的人把袋子放在台子上，上面贴一张小单子。我拿起来看。</p><p>单子上写着：不要冰。</p><p>三个字。我站在那里看了很久。她每次给我点东西都加这三个字，加到六年，加到她今天早上坐在医院台阶上想事情的时候，手上打的还是这三个字。</p><p>我把那张单子撕下来，对折，塞进包最外面那一格。</p><p>回到座位我打开改签那个页面。</p><p>我本来两点二十就走。我把那一班退了，改到晚上七点。差价八十多，我付了。</p><p>付完我忽然不知道这多出来的四个多小时要拿去干什么。</p><p>我在 B 口坐着。这一层一共十九排椅子，我一排一排数过。九点半以后开始有人来坐着，都是看手机的。有个男的抱着一个保温杯坐到我旁边，他每四十分钟去接一次热水。</p><p>第三次他接水回来，坐下的时候问我，等人？</p><p>我说等完了。</p><p>他说那你怎么不走。</p><p>我说我改签到七点。</p><p>他把杯盖拧上，扭头看了我一下。</p><p>他说，你等的人没来。</p><p>我说没有。</p><p>他说那你不恨她。</p><p>我说我不恨。</p><p>他把杯盖拧得很紧，又拧开一度。这个动作他做了一遍才开口。</p><p>他说那你为什么改到七点。</p><p>我说因为我今天要是现在出去，我下午回到公司也没地方去，晚上我还要跟我妈讲今天这一天。我今天讲不出来。</p><p>那个人&quot;哦&quot;了一声。他把保温杯放在膝盖上，看着对面那块不停跳的航班屏。屏上有一班红了，写着延误两个小时，后面又来一班，红的换到另一行去了。</p><p>他讲了两句话。我到现在还留着。</p><p>他说，你们这些小孩，什么都拿一张嘴接着。他说人讲话这个东西要隔一夜，你今天不讲，不是因为你不想讲，是因为你今天还没想好你要讲给谁。</p><p>我说我讲过给谁，今天讲过。</p><p>他没接这句。他站起来去接第四次水。</p><p>下午两点五十，她发来一张照片。</p><p>一张排椅，不锈钢的，扶手那里缠了一圈白胶带，胶带已经脏成灰色。她说她在那上面坐了一天。她说她们那排从门口数第三排就是坏的，她一直不敢往后靠。</p><p>她把手机往后又拍了一点，我看不太清，只能看见一截病号服的袖子放在膝盖上，和她妈的一双黑布鞋。</p><p>我说我也在第三排。</p><p>她说你看，你今天也承认了。</p><p>她说我们两个今天坐在同一把椅子上，不一样的城市，不一样的人。</p><p>那天下午我在机场待到六点四十。我把那杯咖啡喝了，太苦。面包我没吃，我把它带回住处，第二天早上热了一下吃了。</p><p>七点的飞机上我睡着了一次，醒来的时候机舱里在放饭，空姐推着车从过道过去，铝盒碰撞的声音一路响。</p><p>我落地八点二十。到家我洗了脸，屏幕亮了一下。</p><p>是她。她说她妈今天吃药以后睡了，她在楼下买了一份面，六块，不好吃，她把汤喝完了。</p><p>我坐在床沿上把那条看了三遍。</p><p>她妈血压高、她在台阶上坐了一上午、我改签花了八十多、她给我点了一个四十块的早餐——这一天所有的事，最后落到一份六块的面，她一个人坐在楼下的桌子上把它吃完。</p><p>我说那挺好。</p><p>她回：你又&quot;那挺好&quot;。</p><p>我说我今天想不出别的。</p><p>她说你想不出别的，你就早点睡。</p><p>那天夜里我把桌上那个纸袋子拿起来，把&quot;不要冰&quot;那张单子从里面抽出来，夹进本子里。</p><p>我夹到&quot;这个我们以后还会遇到&quot;那一页后面。</p>',72)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
